// Internal GitHub Actions module; no standalone CLI or third-party dependencies.
const fs = require('node:fs');
const path = require('node:path');

const DAY = 86400000;
const month = (date) => date.toISOString().slice(0, 7);
const integer = (value) => Number.isSafeInteger(value) && value >= 0;
const escape = (text) => String(text).replace(/[&<>"']/g, (char) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&apos;',
})[char]);

function monthlySeries(repository, weeks, now = new Date()) {
  const created = new Date(repository.created_at);
  if (!Number.isFinite(+created) || !Number.isFinite(+now) || created > now ||
      !integer(repository.stargazers_count) || !Array.isArray(weeks)) {
    throw new Error('Invalid repository metadata or star history.');
  }
  if (weeks.length === 0 && repository.stargazers_count > 0) {
    throw new Error('Star history is missing for a repository with stars.');
  }

  // GitHub reports daily star additions in weeks beginning on Sunday:
  // https://www.star-history.com/blog/new-github-star-history-api/
  const additions = new Map();
  const seen = new Set();
  const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  for (const week of weeks) {
    if (!integer(week.week) || !Number.isFinite(week.week * 1000) ||
        !Array.isArray(week.days) || week.days.length !== 7 ||
        !week.days.every(integer) || seen.has(week.week)) {
      throw new Error('Invalid or duplicate week in star history.');
    }
    seen.add(week.week);
    week.days.forEach((count, index) => {
      const date = new Date(week.week * 1000 + index * DAY);
      if (!Number.isFinite(+date)) throw new Error('Invalid star history date.');
      if (+date <= today && month(date) >= month(created)) {
        const key = month(date);
        additions.set(key, (additions.get(key) || 0) + count);
      }
    });
  }

  const series = [];
  let count = 0;
  const cursor = new Date(Date.UTC(created.getUTCFullYear(), created.getUTCMonth(), 1));
  while (month(cursor) <= month(now)) {
    const key = month(cursor);
    count += additions.get(key) || 0;
    if (!integer(count)) throw new Error('Star count exceeds safe integer range.');
    series.push({ month: key, count });
    cursor.setUTCMonth(cursor.getUTCMonth() + 1);
  }
  // Keep the current month accurate when stars are removed or history is cached.
  series[series.length - 1].count = repository.stargazers_count;
  return series;
}

function renderChart(repository, series, theme) {
  if (!['light', 'dark'].includes(theme) || series.length === 0) {
    throw new Error('A supported theme and monthly series are required.');
  }
  const colors = theme === 'dark'
    ? { background: '#0d1117', text: '#e6edf3', muted: '#9198a1', grid: '#30363d', line: '#58a6ff' }
    : { background: '#ffffff', text: '#1f2328', muted: '#656d76', grid: '#d1d9e0', line: '#0969da' };
  const left = 64, right = 766, top = 96, bottom = 272;
  const maximum = Math.max(1, ...series.map((point) => point.count));
  const step = Math.max(1, Math.ceil(maximum / 4));
  const ceiling = Math.ceil(maximum / step) * step;
  const x = (index) => series.length === 1 ? (left + right) / 2
    : left + index * (right - left) / (series.length - 1);
  const y = (count) => bottom - count * (bottom - top) / ceiling;
  const number = (value) => value.toFixed(2);
  const current = series[series.length - 1].count;
  const svg = [
    '<svg xmlns="http://www.w3.org/2000/svg" width="800" height="352" viewBox="0 0 800 352" role="img" aria-labelledby="title description">',
    '<!-- Generated by .github/star-history.cjs. Do not edit. -->',
    `<title id="title">Monthly Star History for ${escape(repository.full_name)}</title>`,
    `<desc id="description">${current} stars. UTC calendar months from ${series[0].month} to ${series[series.length - 1].month}.</desc>`,
    `<rect x="0.5" y="0.5" width="799" height="351" rx="12" fill="${colors.background}" stroke="${colors.grid}"/>`,
    '<g font-family="-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif">',
    `<text x="32" y="38" fill="${colors.text}" font-size="20" font-weight="600">Star History</text>`,
    `<text x="32" y="62" fill="${colors.muted}" font-size="13">${escape(repository.full_name)}</text>`,
    `<text x="766" y="38" text-anchor="end" fill="${colors.line}" font-size="18" font-weight="600">${current.toLocaleString('en-US')} stars</text>`,
  ];
  for (let count = 0; count <= ceiling; count += step) {
    svg.push(`<line x1="${left}" x2="${right}" y1="${number(y(count))}" y2="${number(y(count))}" stroke="${colors.grid}"/>`);
    svg.push(`<text class="y-tick" x="52" y="${number(y(count) + 4)}" text-anchor="end" fill="${colors.muted}" font-size="12">${count.toLocaleString('en-US')}</text>`);
  }
  const tickCount = Math.min(7, series.length);
  for (let tick = 0; tick < tickCount; tick++) {
    const index = tickCount === 1 ? 0 : Math.round(tick * (series.length - 1) / (tickCount - 1));
    svg.push(`<text class="x-tick" x="${number(x(index))}" y="300" text-anchor="middle" fill="${colors.muted}" font-size="12">${series[index].month}</text>`);
  }
  // A single month gets a horizontal segment instead of a collapsed date scale.
  const line = series.length === 1
    ? `M${left},${number(y(current))} L${right},${number(y(current))}`
    : series.map((point, index) => `${index ? 'L' : 'M'}${number(x(index))},${number(y(point.count))}`).join(' ');
  svg.push(`<path class="star-line" d="${line}" fill="none" stroke="${colors.line}" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>`);
  svg.push(`<circle cx="${number(x(series.length - 1))}" cy="${number(y(current))}" r="4" fill="${colors.line}"/>`);
  if (series.every((point) => point.count === 0)) {
    svg.push(`<text x="415" y="180" text-anchor="middle" fill="${colors.muted}" font-size="14">No stars yet</text>`);
  }
  svg.push(`<text x="415" y="331" text-anchor="middle" fill="${colors.muted}" font-size="12">Month (UTC)</text>`, '</g>', '</svg>');
  return svg.join('\n') + '\n';
}

async function updateCharts({ github, repo, directory, now = new Date() }) {
  const [response, weeks] = await Promise.all([
    github.rest.repos.get(repo),
    github.paginate('GET /repos/{owner}/{repo}/stargazers/history', { ...repo, per_page: 30 }),
  ]);
  const series = monthlySeries(response.data, weeks, now);
  const charts = ['light', 'dark'].map((theme) => ({
    file: path.join(directory, `star-history-${theme}.svg`),
    content: renderChart(response.data, series, theme),
  }));
  // Do not replace either image if fetching, validation or rendering fails.
  fs.mkdirSync(directory, { recursive: true });
  for (const chart of charts) fs.writeFileSync(chart.file, chart.content);
  return charts.map((chart) => chart.file);
}

module.exports = { monthlySeries, renderChart, updateCharts };
